{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "لأنه يشبه أباً له ابن وحيد يُسلَّم للعقاب، والذين يرون أباه ويعزونه يغطون وجهه لكيلا يرى كيف يُعاقب ابنه، فيزداد تمزقاً بالحزن.",
      "verse": 26
    },
    {
      "chapter": 7,
      "text_ar": "لأنه هكذا أشفق الله عليكم ولم يدعكم تدخلون بابل لكيلا تروا ضيق الشعب.",
      "verse": 27
    },
    {
      "chapter": 7,
      "text_ar": "لأنه منذ أن أتينا إلى هنا لم يفارقنا الحزن، طوال ست وستين سنة حتى اليوم.",
      "verse": 28
    },
    {
      "chapter": 7,
      "text_ar": "لأنه مرات عديدة عندما خرجتُ وجدتُ بعض الشعب معلقين بأمر الملك نبوخذ نصر، وهم يبكون ويقولون: «اർحمنا أيها الإله زار!»",
      "verse": 29
    },
    {
      "chapter": 7,
      "text_ar": "فلما سمعتُ هذا، حزنتُ وبكيتُ بنوح مضاعف، ليس فقط لأنهم كانوا معلقين، بل لأنهم كانوا يدعون إلهاً غريباً قائلين: «ارحمنا».",
      "verse": 30
    }
  ]
}
